    else:
        if ample_supply:
            bid = min(budget, 16.0)
        elif tight_supply:
            if high_prev >= 120.0:
                bid = min(budget, 34.0)
            elif high_prev >= 70.0:
                bid = min(budget, 42.0)
            else:
                bid = min(budget, 48.0)
        else:
            if high_prev >= 120.0:
                bid = min(budget, 22.0)
            elif high_prev >= 70.0:
                bid = min(budget, 30.0)
            else:
                bid = min(budget, 38.0)

